def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 96:
        return 'D'
    opp = [a for _, a in history]
    my = [a for a, _ in history]
    opp_last = opp[-1]
    my_last = my[-1]
    opp_d_total = 0
    my_d_total = 0
    for a in opp:
        if a == 'D':
            opp_d_total += 1
    for a in my:
        if a == 'D':
            my_d_total += 1
    last8 = opp[-8:]
    opp_d8 = 0
    for a in last8:
        if a == 'D':
            opp_d8 += 1
    if n < 6:
        return 'C'
    if n < 12:
        if opp_d_total >= 2:
            return 'D'
        return 'C'
    opp_rate = opp_d_total / float(n)
    if opp_last == 'D':
        if opp_d8 >= 4 or opp_rate > 0.45:
            return 'D'
        if my_last == 'D':
            return 'D'
        return 'D'
    if opp_d8 >= 5:
        return 'D'
    if opp_rate > 0.5:
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    if opp_rate <= 0.12:
        if my_d_total > opp_d_total + 2:
            return 'C'
        if n > 25 and n % 13 == 0:
            return 'D'
        return 'C'
    if opp_rate <= 0.3:
        return 'C'
    if opp_rate <= 0.45:
        if rng.random() < 0.25:
            return 'D'
        return 'C'
    return 'D'
